package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;

public class AccountDevicesActivity extends FragmentActivity {
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}LinearLayout page=VaultPageUi.page(this);page.addView(VaultPageUi.header(this,"Account And Devices","Secure access points"));page.addView(VaultPageUi.section(this,"Your Devices"));String model=Build.MANUFACTURER+" "+Build.MODEL;VaultPageUi.addRow(page,VaultPageUi.iconRow(this,"user",model,"This device · Active now"));LinearLayout portal=VaultPageUi.iconRow(this,"folder","My Vault PC Portal","Browser access with two-step verification");portal.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://badimps.github.io/secure-document-wallet/"))));VaultPageUi.addRow(page,portal);page.addView(VaultPageUi.sectionHead(this,"Two-Step Verification","Enabled"));page.addView(VaultPageUi.notice(this,"✓","Email Backup Code","Codes return to the PC portal after verification",Ui.SOFT,Ui.TEAL));TextView pair=VaultPageUi.primary(this,"Pair A New Computer");pair.setOnClickListener(v->portal.performClick());VaultPageUi.button(page,pair);setContentView(VaultPageUi.screen(this,page,"profile"));}
}
